from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Detect rectangular monochrome outlines by their complete perimeter.
    frames = []
    for r0 in range(h):
        for r1 in range(r0 + 2, h):
            for c0 in range(w):
                for c1 in range(c0 + 2, w):
                    color = out[r0][c0]
                    if color == 0:
                        continue
                    if (all(out[r0][c] == color and out[r1][c] == color for c in range(c0,c1+1))
                        and all(out[r][c0] == color and out[r][c1] == color for r in range(r0,r1+1))):
                        if all(out[r][c] == 0 for r in range(r0+1,r1) for c in range(c0+1,c1)):
                            frames.append((color,r0,r1,c0,c1))
    # Keep smallest actual rectangles (the perimeter search can find larger composites).
    frames = [f for f in frames if not any(g != f and f[1] <= g[1] and f[2] >= g[2] and f[3] <= g[3] and f[4] >= g[4] for g in frames)]
    inside = {(r,c) for _,a,b,x,y in frames for r in range(a,b+1) for c in range(x,y+1)}
    dots = Counter(out[r][c] for r in range(h) for c in range(w) if out[r][c] and (r,c) not in inside)
    # Loose colored dots are the pattern source; remove them after counting.
    for r in range(h):
        for c in range(w):
            if (r,c) not in inside:
                out[r][c] = 0
    for _,r0,r1,c0,c1 in frames:
        cells = [(r,c) for r in range(r0+1,r1) for c in range(c0+1,c1) if (r-r0-1+c-c0-1)%2==0]
        n=len(cells)
        options=[col for col,count in dots.items() if count==n]
        if len(options)==1:
            color=options[0]
            for r,c in cells: out[r][c]=color
            dots[color]=0
    return out
